Lemma tden_map_scale : forall E sc ts,
  tden E (List.map (fun t => ((sc * fst t)%Z, snd t)) ts) = (sc * tden E ts)%Z.
Proof. intros E sc ts. induction ts as [|[k a] rest IH]; cbn [List.map tden fst snd]; [lia|]. rewrite IH. lia. Qed.
